using System;using System.IO;using System.Diagnostics;using System.Drawing;using System.Globalization;using System.Security.Principal;using System.Threading;using System.Windows.Forms;using ThinkPadModesV3;
internal static class SimpleCpuApp {
 static string Root= @"C:\ProgramData\ThinkPadModes\CpuSimple";
 [STAThread] public static int Main(string[] a){
 try{if(a.Length==1&&a[0]=="--verify-direct-rpm")return DirectRpmSession.Verify();if(a.Length==4&&a[0]=="--direct-rpm")return DirectRpmSession.Run(Path.GetDirectoryName(a[1]),a[2],a[3]);if(a.Length>0&&(a[0]=="--sdk"||a[0]=="--read"))return ZeroDbCalibrator.Main(a);if(a.Length==2&&a[0]=="--watch"){try{using(var p=Process.GetProcessById(Int32.Parse(a[1])))p.WaitForExit();}catch(ArgumentException){}if(File.Exists(Path.Combine(Root,"fan-active"))){try{ForcedZeroReader.EmergencyAuto(0);CoolingClient.Send("resume-acquisition");File.Delete(Path.Combine(Root,"fan-active"));}catch{}}new ZeroPowerLease(Path.Combine(Root,"lease.json"),true);return 0;}
 if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)){Process.Start(new ProcessStartInfo(typeof(SimpleCpuApp).Assembly.Location){UseShellExecute=true,Verb="runas"});return 0;}
 foreach(var old in Process.GetProcessesByName("ThinkPad-CPU")){if(old.Id==Process.GetCurrentProcess().Id)continue;try{if(old.MainWindowHandle!=IntPtr.Zero){old.CloseMainWindow();if(!old.WaitForExit(8000))throw new IOException("Ferme la précédente fenêtre CPU avant de continuer.");}}finally{old.Dispose();}}foreach(var old in Process.GetProcessesByName("ThinkPad-CPU")){if(old.Id==Process.GetCurrentProcess().Id)continue;using(old){if(!old.WaitForExit(8000))throw new IOException("Ancienne session CPU encore active.");}}
 bool fresh;using(var mutex=new Mutex(true,@"Global\ThinkPadModes.Calibration",out fresh)){if(!fresh)throw new IOException("Un autre essai CPU est actif. Ferme-le avant de continuer.");Directory.CreateDirectory(Root);string journal=Path.Combine(Root,"lease.json");if(File.Exists(journal))new ZeroPowerLease(journal,true);Application.EnableVisualStyles();using(var f=new CpuWindow(Root,journal))Application.Run(f);}return 0;
 }catch(Exception e){MessageBox.Show(e.Message,"ThinkPad CPU — erreur",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
internal sealed class CpuWindow:Form {
 readonly Label temp=new Label(),info=new Label(),fans=new Label();readonly Button zero=new Button(),automatic=new Button();ForcedZeroReader fanReader;bool paused,everFresh,zeroWanted;long fanBegin,zeroBegan,autoQualifiedSince,lastSequence=-1;int zeroFrames;readonly string fanMarker;readonly Button b15=new Button(),b20=new Button();readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();readonly CalibrationCpu cpu;readonly PawnModule msr;readonly StreamWriter csv;readonly string journal;ZeroPowerLease lease;int watts;double previousEnergy;long previousTime;readonly Stopwatch clock=Stopwatch.StartNew();bool tripped;readonly string folder;
 public CpuWindow(string root,string j){journal=j;fanMarker=Path.Combine(root,"fan-active");folder=Path.Combine(root,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(folder);cpu=new CalibrationCpu();var i=Paths.Info();msr=new PawnModule("IntelMSR.bin",Path.Combine(Paths.Root,"versions",i.Version,"modules"));csv=new StreamWriter(Path.Combine(folder,"mesures.csv"),false,System.Text.Encoding.UTF8);csv.AutoFlush=true;csv.WriteLine("utc;limite_W;cpu_C;cpu_W;etat;fan1_rpm;fan2_rpm;fan_mode");Text="ThinkPad CPU — test manuel";AutoScaleMode=AutoScaleMode.Dpi;ClientSize=new Size(560,430);MinimumSize=new Size(500,440);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",11);var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(18)};Controls.Add(panel);temp.AutoSize=true;temp.Font=new Font("Segoe UI",25,FontStyle.Bold);temp.Text="Lecture CPU…";panel.Controls.Add(temp);fans.AutoSize=true;fans.MaximumSize=new Size(500,0);fans.Text="Ventilateurs : lecture Lenovo en préparation…";panel.Controls.Add(fans);var fanButtons=new FlowLayoutPanel{AutoSize=true};zero.Text="0 dB surveillé";zero.Size=new Size(180,44);zero.Enabled=false;automatic.Text="Retour Auto";automatic.Size=new Size(160,44);zero.Click+=(s,e)=>StartZero();automatic.Click+=(s,e)=>{try{if(fanReader==null){InitFans();return;}if(fanReader!=null)fanReader.Set(128);zeroWanted=false;zeroFrames=0;fans.Text="Auto demandé — mesure attendue";}catch(Exception ex){StopFans(ex.Message);}};fanButtons.Controls.Add(zero);fanButtons.Controls.Add(automatic);panel.Controls.Add(fanButtons);info.AutoSize=true;info.MaximumSize=new Size(450,0);info.Text="Choisis un plafond, puis lance ton burn. Ventilation Auto.";panel.Controls.Add(info);var buttons=new FlowLayoutPanel{AutoSize=true};foreach(var b in new[]{b15,b20}){b.Size=new Size(120,44);buttons.Controls.Add(b);}b15.Text="15 W";b20.Text="20 W";b15.Click+=(s,e)=>Apply(15);b20.Click+=(s,e)=>Apply(20);var restore=new Button{Text="Restaurer",Size=new Size(120,44)};restore.Click+=(s,e)=>Restore();buttons.Controls.Add(restore);panel.Controls.Add(buttons);var logs=new Button{Text="Ouvrir les mesures",AutoSize=true};logs.Click+=(s,e)=>Process.Start(new ProcessStartInfo(folder){UseShellExecute=true});panel.Controls.Add(logs);panel.Controls.Add(new Label{Text="Boost désactivé pendant le plafond. À 90 °C : repli 8 W et alerte.\nFermer restaure les réglages CPU. CPU ≥90 °C / GPU ≥80 °C ou perte de mesures : Auto. Aucun burn lancé.",AutoSize=true,MaximumSize=new Size(450,0)});
 Process.Start(new ProcessStartInfo(typeof(SimpleCpuApp).Assembly.Location,"--watch "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true});Shown+=(s,e)=>{Apply(15);InitFans();};timer.Interval=500;timer.Tick+=(s,e)=>Sample();timer.Start();FormClosing+=(s,e)=>{timer.Stop();StopFans("Fermeture — Auto");try{Restore();}catch(Exception ex){MessageBox.Show(ex.Message+"\nLe journal de restauration est conservé.");}};FormClosed+=(s,e)=>{csv.Dispose();cpu.Dispose();msr.Dispose();};}
 void Restore(){if(zeroWanted){if(fanReader!=null)fanReader.Set(128);zeroWanted=false;zeroFrames=0;}if(lease!=null){lease.Dispose();lease=null;}watts=0;info.Text="Réglages CPU restaurés. Mesures enregistrées.";}
 void Apply(int w){try{if(zeroWanted){info.Text="Reviens en Auto avant de changer le plafond.";return;}if(tripped)throw new IOException("Seuil thermique atteint : ferme le burn puis relance l’app.");Restore();lease=new ZeroPowerLease(journal,false,w);watts=w;info.Text="Plafond "+w+" W vérifié — lance ton burn manuellement.";}catch(Exception e){info.Text="Erreur : "+e.Message;}}
 void InitFans(){try{LenovoOemTransport.Verify();var status=CoolingClient.Send("status");if(!status.Ok)throw new IOException(status.Error);if(status.Snapshot.Faulted){var fault=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(Path.Combine(CoolingPaths.Data,"fault.json")));if(!Convert.ToBoolean(fault["AutomaticRestored"])||fault["RecoveryError"]!=null)throw new IOException("Retour Auto du service non confirmé");}var pause=CoolingClient.Send("pause");if(!pause.Ok)throw new IOException(pause.Error);paused=true;using(var ec=new LenovoOemTransport(true))ec.SetBothOem(128);File.WriteAllText(fanMarker,"Auto; surveillance active");fanReader=new ForcedZeroReader(folder,true);everFresh=false;autoQualifiedSince=0;fanBegin=CoolingPaths.Tick;}catch(Exception e){StopFans(e.Message);}}
 void StopFans(string reason){zero.Enabled=false;zeroWanted=false;zeroFrames=0;bool restored=true;try{if(fanReader!=null){fanReader.Dispose();fanReader=null;}}catch(Exception e){restored=false;reason+=" ; Auto : "+e.Message;}try{if(paused){var r=CoolingClient.Send("resume-acquisition");if(!r.Ok)throw new IOException(r.Error);paused=false;}}catch(Exception e){reason+=" ; lecteur : "+e.Message;}if(restored&&File.Exists(fanMarker))File.Delete(fanMarker);fans.Text="Auto — "+reason;}
 void StartZero(){try{if(fanReader==null||lease==null||!lease.Verified||!WindowsPower.OnMains())throw new IOException("Plafond CPU vérifié et secteur nécessaires");using(var gpu=new NvmlTelemetry()){var g=gpu.Read()["GpuTemperature"];if(cpu.Temperature()>60||!g.Value.HasValue||g.Status!="valid"||g.Value.Value>50)throw new IOException("Attends CPU ≤60 °C et GPU ≤50 °C avant l’arrêt initial.");}fanReader.Pulse();var f=fanReader.Snapshot();if(f.Actual!="Auto"||!f.Fan1.HasValue||!f.Fan2.HasValue)throw new IOException("RPM Auto frais requis");fanReader.Set(0);zeroWanted=true;zeroBegan=CoolingPaths.Tick;zeroFrames=0;fans.Text="Arrêt forcé demandé — confirmation RPM attendue";}catch(Exception e){try{if(fanReader!=null)fanReader.Set(128);}catch{}zeroWanted=false;info.Text=e.Message;}}
 void Sample(){try{double c=cpu.Temperature();double unit=Math.Pow(.5,(int)((msr.Execute("ioctl_read_msr",0x606)>>8)&31));double energy=(msr.Execute("ioctl_read_msr",0x611)&0xffffffffUL)*unit;long now=clock.ElapsedMilliseconds;double p=previousTime==0?Double.NaN:(energy>=previousEnergy?energy-previousEnergy:energy+4294967296.0*unit-previousEnergy)*1000/(now-previousTime);previousTime=now;previousEnergy=energy;temp.Text=c.ToString("F0")+" °C   ·   "+(Double.IsNaN(p)?"—":p.ToString("F1"))+" W";CoolingSnapshot fan=null;if(fanReader!=null){fanReader.Pulse();try{fan=fanReader.Snapshot();everFresh=true;if(!zeroWanted&&fan.Actual=="Auto"){if(autoQualifiedSince==0)autoQualifiedSince=CoolingPaths.Tick;}else if(!zeroWanted)autoQualifiedSince=0;zero.Enabled=!tripped&&autoQualifiedSince>0&&CoolingPaths.Tick-autoQualifiedSince>=30000;bool bothZero=fan.Actual=="Zero"&&fan.Fan1==0&&fan.Fan2==0;if(fanReader.Sequence!=lastSequence){lastSequence=fanReader.Sequence;zeroFrames=zeroWanted&&bothZero?zeroFrames+1:0;}fans.Text="Ventilateur 1 : "+fan.Fan1+" tr/min   ·   Ventilateur 2 : "+fan.Fan2+" tr/min\n"+(zeroWanted?(zeroFrames>=3?"0 dB confirmé : deux tachymètres à zéro":"0 dB demandé — confirmation attendue"):((autoQualifiedSince>0&&CoolingPaths.Tick-autoQualifiedSince<30000)?"Auto — vérification lecture directe "+((CoolingPaths.Tick-autoQualifiedSince)/1000)+"/30 s":"Auto Lenovo"))+" · mesure "+(fan.FrameAgeMs/1000.0).ToString("F1")+" s";if(zeroWanted&&zeroFrames<3&&CoolingPaths.Tick-zeroBegan>30000)throw new IOException("Deux RPM zéro non confirmés en 30 s");if(zeroWanted&&!WindowsPower.OnMains())throw new IOException("Secteur débranché");}catch(Exception ex){if(everFresh||CoolingPaths.Tick-fanBegin>20000)StopFans("RPM indisponibles : "+ex.Message);}}
 if(c>=90&&!tripped){tripped=true;StopFans("90 °C CPU — Auto rétabli");Restore();lease=new ZeroPowerLease(journal,false,8);watts=8;b15.Enabled=b20.Enabled=false;info.Text="90 °C : repli à 8 W. ARRÊTE LE BURN.";System.Media.SystemSounds.Hand.Play();}if(lease!=null&&!lease.Verified)throw new IOException("Plafond modifié extérieurement : arrête le burn.");csv.WriteLine(DateTime.UtcNow.ToString("o")+";"+watts+";"+c.ToString(CultureInfo.InvariantCulture)+";"+(Double.IsNaN(p)?"":p.ToString("F3",CultureInfo.InvariantCulture))+";"+(tripped?"ALERTE":fan==null?"RPM_INDISPONIBLES":"OK")+";"+(fan==null?"":fan.Fan1.ToString())+";"+(fan==null?"":fan.Fan2.ToString())+";"+(fan==null?"inconnu":fan.Actual));}catch(Exception e){timer.Stop();StopFans("Erreur capteur — Auto");b15.Enabled=b20.Enabled=false;info.Text="ARRÊTE LE BURN : "+e.Message;System.Media.SystemSounds.Hand.Play();csv.WriteLine(DateTime.UtcNow.ToString("o")+";;;;ERREUR "+e.Message.Replace(';',','));}}
}
